-- TOYBLAST
-- Do not edit this file. Any change breaks the decoder.
local _wasrua = 217
local _segllt = 8
local _edtzyw = 119
local _cahtvr = ""

local _rakjye = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _xpqsjd(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ciogov(d)
	d = d:gsub("[^" .. _rakjye .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_rakjye:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ihhjmp = _ciogov(_cahtvr)
local _xnnfoi = { _wasrua, _segllt, _edtzyw }
local _ujsphw = {}
for i = 1, #_ihhjmp do
	_ujsphw[i] = string.char(_xpqsjd(_ihhjmp:byte(i), _xnnfoi[(i - 1) % 3 + 1]))
end

local _kteeuh = load or loadstring
local _gcyvss, _yxukuk = _kteeuh(table.concat(_ujsphw), "=w")
if not _gcyvss then
	gg.alert("Corrupted file: " .. tostring(_yxukuk))
	os.exit()
end
_gcyvss()
